var t=`0680-malian-jollof-rice`;var o=`world-0680`;var n=`ML`;var a=`western-africa`;var r=4;var s=51;var l={en:`Malian Jollof Rice`,ua:`Джолоф по-малійськи`};var d={en:`Malian Jollof Rice is a Mali classic prepared with yellow onion, tomato, tomato paste, parboiled rice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Джолоф по-малійськи, страва кухні країни Малі зі складниками: жовта цибуля, помідор, томатна паста, пропарений рис. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,190,`g`],[`tomato`,450,`g`],[`tomato-paste`,50,`g`],[`sunflower-oil`,55,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`parboiled-rice`,370,`g`],[`water`,690,`ml`],[`chicken-stock`,200,`ml`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 9 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 9 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-bell-pepper`,170,`g`],[`parsley`,18,`g`]]}];var u={slug:t,id:o,country:`ML`,region:a,servings:4,minutes:51,title:l,text:d,steps:g};export{n as country,u as default,o as id,s as minutes,a as region,r as servings,t as slug,g as steps,d as text,l as title};